  function frame(){if(!S.project)return [1920,1080];const r=recipe();if(r.aspect==="source"&&r.clips[0]){const m=asset(r.clips[0].asset_id).metadata;return [m.width,m.height];}const v=Number(r.resolution)||1080;return r.aspect==="9:16"?[v,Math.floor(v*16/9/2)*2]:r.aspect==="1:1"?[v,v]:[Math.floor(v*16/9/2)*2,v];}
  function layout(){tools.layoutDirty=false;const area=$(".program-area"),stage=$("#studio-stage"),[w,h]=frame();const scale=Math.min(area.clientWidth/w,area.clientHeight/h);stage.style.width=Math.max(1,w*scale)+"px";stage.style.height=Math.max(1,h*scale)+"px";$("#studio-frame-label").textContent=w+" × "+h;const at=locate(S.time),v=$("#studio-video");if(at&&v.videoWidth){const g=M.geometry(v.videoWidth,v.videoHeight,{mode:at.c.fit},stage.clientWidth,stage.clientHeight);Object.assign(v.style,{left:g.x+"px",top:g.y+"px",width:g.w+"px",height:g.h+"px"});}}
